// Rewriter: expand + extract filters (deterministic rules + model fallback in prod)
function rewriteQuery(q) {
  const out = { queries: [q], filters: {} };
  const budget = q.match(/under \$(\d+)|cheap|budget/i);
  if (budget) out.filters.maxPrice = budget[1] ? Number(budget[1]) : 100;
  const size = q.match(/size\s*(\d+)/i);
  if (size) out.filters.size = Number(size[1]);
  const expansions = {
    comfy: ["cushioned", "supportive", "padded"],
    cheap: ["budget", "affordable", "under $100"],
    walks: ["walking", "long-distance", "all-day"],
  };
  for (const [k, syns] of Object.entries(expansions))
    if (new RegExp(k, "i").test(q)) out.queries.push(...syns.map((s) => q.replace(new RegExp(k, "i"), s)));
  return out;
}
// Rules handle the known vocabulary; model rewriting covers the long tail.

